before:
Run this complete type setup in a TypeScript runner:
```typescript
type Details = {
  selected: { label: string };
  counted: { count: number };
};
type EventName = keyof Details;
type SelectedDetails = Details['selected'];
const detail: SelectedDetails = { label: 'Cedar' };
console.log(detail.label);
```
It prints Cedar. keyof Details produces the union 'selected' | 'counted'. Details['selected'] is an indexed access type: it looks up the type of that property. Those brackets operate on types here, not on a runtime Details object. A type alias does not create such an object.

Continue in the same TypeScript file:
```typescript
type PayloadFor<K extends keyof Details> =
  K extends keyof Details ? Details[K] : never;
type DemoEvent = {
  [K in keyof Details]: {
    type: K;
    payload: PayloadFor<K>;
  }
}[keyof Details];
function message(event: DemoEvent): string {
  if (event.type === 'selected') {
    return `Selected ${event.payload.label}`;
  }
  return `Count ${event.payload.count}`;
}
console.log(message({ type: 'selected', payload: detail }));
console.log(message({ type: 'counted', payload: { count: 6 } }));
```
The outputs are Selected Cedar and Count 6. The type declaration does no runtime loop; the handler is ordinary running code.

after:
This example keeps each name connected to its own payload.
```typescript
type Details = {
  selected: { label: string };
  counted: { count: number };
};
type PayloadFor<K extends keyof Details> =
  K extends keyof Details ? Details[K] : never;
type DemoEvent = {
  [K in keyof Details]: { type: K; payload: PayloadFor<K> }
}[keyof Details];
function message(event: DemoEvent): string {
  if (event.type === "selected") {
    return `Selected ${event.payload.label}`;
  }
  return `Count ${event.payload.count}`;
}
console.log(message({ type: "selected", payload: { label: "Cedar" } }));
```
The output is Selected Cedar.
